class MissingArtifact(Exception):pass
class VerificationFailure(Exception):pass

def sha_file(p):
 h=hashlib.sha256()
 with open(p,'rb') as f:
  for b in iter(lambda:f.read(4*1024**2),b''):h.update(b)
 return h.hexdigest()
def js(p,x):Path(p).write_text(json.dumps(x,indent=2,default=str,allow_nan=False),encoding='utf-8')
def origin(a):return a['path']+('::'+a['member'] if a.get('member') else '')
def data_bytes(a):
 if a.get('member'):
  with zipfile.ZipFile(a['path']) as z,z.open(a['member']) as f:b=f.read(128*1024**2+1)
 else:
  with open(a['path'],'rb') as f:b=f.read(128*1024**2+1)
 if len(b)>128*1024**2:raise VerificationFailure('Selected result asset exceeds bounded read: '+origin(a))
 return b

def render_block(text,live=True):
 # These are renderings of saved results, not invented experimental executions.
 identifier='render_'+str(len(CELLS))
 CELLS.append({'cell_type':'code','id':identifier,'execution_count':None,'metadata':{'purpose':'rendering saved results only'},
   'source':['# Rendering saved result text; no model fit or experimental execution.\n','print('+repr(text)+')\n'],
   'outputs':[{'output_type':'stream','name':'stdout','text':[text+'\n']}]})
 if live:print(text,flush=True)

def section(title):
 render_block('\n'+'='*92+'\n'+title+'\n'+'='*92)

def table_text(frame):
 with pd.option_context('display.max_rows',None,'display.max_columns',None,'display.max_colwidth',None,'display.width',None):
  return frame.to_string(index=False,max_rows=None,max_cols=None,line_width=None,max_colwidth=None)

def display_table(tag,frame,detail=False):
 frame.to_csv(OUT/'tables'/(tag+'.csv'),index=False)
 TABLES[tag]=frame
 section(tag+' | '+str(len(frame))+' rows x '+str(len(frame.columns))+' columns')
 live=(not detail) or PRINT_DETAIL_ROWS_LIVE
 for start in range(0,len(frame),ROWS_PER_OUTPUT_CELL):
  stop=min(start+ROWS_PER_OUTPUT_CELL,len(frame))
  block=f'{tag}: rows {start+1}–{stop} of {len(frame)}\n'+table_text(frame.iloc[start:stop])
  render_block(block,live=live)
  if live and OUTPUT_PAUSE_SECONDS:time.sleep(OUTPUT_PAUSE_SECONDS)
 if not len(frame):render_block('[Empty table; columns: '+', '.join(frame.columns)+']',live=live)
 if not live:render_block('All detail rows retained in the paginated report notebook; live detail display disabled explicitly.')

