def wanted_name(name):
 n=name.lower()
 return n in {x[1].lower() for x in SPECS} or n in {'receipt.json','ledger.json','completion_scope.json','manifest.json'}

def discover():
 archives=[]
 for root in [WORK,Path('/kaggle/input')]:
  if not root.exists():continue
  for base,dirs,files in os.walk(root):
   bp=Path(base)
   dirs[:]=[x for x in dirs if bp/x!=OUT and x not in {'.git','__pycache__','site-packages'}
            and not x.startswith('.zeek') and x!='iot-2023-dataset-full']
   for name in files:
    p=bp/name
    if p.suffix.lower()=='.zip':archives.append(p)
    elif wanted_name(name) and p.stat().st_size<=128*1024**2:
     INDEX.append({'path':str(p),'member':None,'leaf':name,'size':p.stat().st_size,'archive_identity':None})
 for p in archives:
  try:
   with zipfile.ZipFile(p) as z:
    members=[n for n in z.infolist() if not n.is_dir() and wanted_name(Path(n.filename).name) and n.file_size<=128*1024**2]
    if not members:continue
    archive_identity=None
    if p.name in {'CHECKPOINT.zip','GROUND_TRUTH_PROVENANCE.zip'} or BASE_RUN in str(p) or GT_RUN in str(p):
     digest=sha_file(p)
     archive_identity=next((role for role,h in HASHES.items() if h==digest),None)
    for n in members:INDEX.append({'path':str(p),'member':n.filename,'leaf':Path(n.filename).name,'size':n.file_size,'archive_identity':archive_identity})
  except (OSError,zipfile.BadZipFile):pass
 pd.DataFrame(INDEX).to_csv(OUT/'discovery_index.csv',index=False)
 render_block('Discovered '+str(len(INDEX))+' selected result/receipt candidates. No raw PCAPs or complete millions-row annotation logs are printed.')

DIGESTS={}
def digest(a):
 key=origin(a)
 if key not in DIGESTS:DIGESTS[key]=hashlib.sha256(data_bytes(a)).hexdigest()
 return DIGESTS[key]

def choose(filename,scopes,tag):
 opts=[a for a in INDEX if a['leaf'].lower()==filename.lower() and any(s in origin(a) for s in scopes)]
 # A duplicate backup is acceptable only when its bytes are identical.
 groups=defaultdict(list)
 for a in opts:groups[digest(a)].append(a)
 if len(groups)!=1:
  js(OUT/(tag+'_candidates.json'),{'distinct_contents':len(groups),'candidates':[{'origin':origin(a),'sha256':digest(a)} for a in opts]})
  if not groups:raise MissingArtifact('Saved artifact not found: '+filename+'; no experiment will be rerun.')
  raise VerificationFailure('Different saved contents for '+tag+'; no favorable/latest result selected. Candidate report saved.')
 a=sorted(next(iter(groups.values())),key=origin)[0]
 USED.append({'tag':tag,'source':origin(a),'sha256':digest(a),'verified_archive_identity':a['archive_identity']})
 return a

def load_table(a):
 b=data_bytes(a)
 if b[:2]==b'\x1f\x8b':b=gzip.decompress(b)
 return pd.read_csv(io.BytesIO(b),dtype=str,keep_default_na=False)

def load_outputs():
 for tag,name,scopes,required,detail in SPECS:
  try:
   a=choose(name,scopes,tag);frame=load_table(a)
   (OUT/'original_assets'/(tag+'__'+name)).write_bytes(data_bytes(a))
   display_table(tag,frame,detail)
   STATUS.append({'component':tag,'status':'SAVED_ARTIFACT_LOADED_AND_PRINTED','required_latest_output':required,'rows':len(frame),'columns':len(frame.columns),'detail':origin(a)})
  except Exception as e:
   status='REPORTED_COMPLETE_BUT_ARTIFACT_NOT_MOUNTED' if isinstance(e,MissingArtifact) else 'ARTIFACT_CONFLICT_OR_READ_ERROR'
   STATUS.append({'component':tag,'status':status,'required_latest_output':required,'rows':None,'columns':None,'detail':str(e)})
   section(tag+' — '+status);render_block(str(e))
   if not isinstance(e,MissingArtifact):(OUT/(tag+'_error.txt')).write_text(traceback.format_exc())

# These checks are output-consistency checks, not independent scientific ground truth.
def checks():
 rows=[]
 def check(name,fn):
  try:
   detail=fn();rows.append({'check':name,'status':'PASS','detail':str(detail)})
  except KeyError as e:rows.append({'check':name,'status':'INPUT_NOT_LOADED','detail':str(e)})
  except Exception as e:rows.append({'check':name,'status':'FAIL','detail':str(e)})
 def verify_md3():
  s=TABLES['MD3_WARNING_SUMMARY'];w=TABLES['MD3_MATCHED_WINDOWS']
  assert len(s)==48 and len(w)==576,'Expected48summary and576joined rows'
  key=['variant','ordering','delay_seconds','window','seed']
  assert not w.duplicated(key).any(),'Duplicate variant/window/seed identity'
  assert set(s.variant)=={'CONTINUOUS_FIRST_REQUEST','WINDOW_RESET_DIAGNOSTIC'}
  historical=TABLES['MD3_HISTORICAL_STREAM_CHECKS'];reference=TABLES['MD3_REFERENCE_CHECKS']
  assert len(historical)==8 and historical.matches.str.lower().isin(['true','1']).all()
  assert len(reference)>0 and reference.matches.str.lower().isin(['true','1']).all()
  return '48summary rows;576unique variant/window/seed rows;historical8stream and reference checks passed'
 check('MD3_COMPLETION',verify_md3)
 def verify_benign(prefix,expected_summaries,expected_units):
  s=TABLES[prefix+'_ALL_COHORT_SUMMARY'];u=TABLES[prefix+'_PER_UNIT_OUTCOMES']
  assert len(s)==expected_summaries and len(u)==expected_units
  key=['capture','cohort','family','seed','delay_seconds','rule','label']
  assert not s.duplicated(key).any() and not u.duplicated(key+['ks']).any()
  n=pd.to_numeric(s.original_units);a=pd.to_numeric(s.alarm_units);z=pd.to_numeric(s.no_alarm_units);q=pd.to_numeric(s.unresolved_units)
  assert n.eq(512).all() and (a+z+q).eq(n).all()
  assert np.allclose(pd.to_numeric(s.alarm_fraction_lower),a/n,atol=1e-12,rtol=0)
  assert np.allclose(pd.to_numeric(s.alarm_fraction_upper),(a+q)/n,atol=1e-12,rtol=0)
  counts=u.groupby(key+['state']).size().unstack(fill_value=0).reindex(columns=['ALARM','NO_ALARM','UNRESOLVED'],fill_value=0).reset_index()
  counts=counts.rename(columns={'ALARM':'r_alarm','NO_ALARM':'r_no','UNRESOLVED':'r_unknown'})
  c=s.merge(counts,on=key,how='outer',validate='one_to_one',indicator=True)
  assert c['_merge'].eq('both').all()
  for left,right in [('alarm_units','r_alarm'),('no_alarm_units','r_no'),('unresolved_units','r_unknown')]:
   assert pd.to_numeric(c[left]).eq(c[right]).all()
  benign=s[s.label.eq('0')].copy();unknown=u[u.label.eq('0') & u.state.eq('UNRESOLVED')]
  display_table(prefix+'_BENIGN_ONLY_VERIFIED',benign)
  return str(len(u))+' unit-output rows recounted;'+str(len(benign))+' benign summaries;'+str(unknown.ks.nunique())+' unique unresolved benign keys'
 check('FRESH48_SAVED_OUTCOME_RECOUNT',lambda:verify_benign('FRESH48',108,55296))
 check('HIST49_SAVED_OUTCOME_RECOUNT',lambda:verify_benign('HIST49',36,18432))
 def verify_gt(capture):
  g=TABLES['GT_CAPTURE'+str(capture)+'_PER_UNIT']
  assert len(g)==1024 and not g.ks.duplicated().any()
