def print_receipts():
 section('LATEST SAVED RECEIPTS AND COMPLETION SCOPE')
 opts=[a for a in INDEX if a['leaf'].lower() in {'receipt.json','ledger.json','completion_scope.json'} and
       (BASE_RUN in origin(a) or GT_RUN in origin(a) or 'FINISH_SAVED_EXPERIMENTS_' in origin(a) or a['archive_identity'])]
 seen=set()
 for a in sorted(opts,key=origin):
  try:
   b=data_bytes(a);h=hashlib.sha256(b).hexdigest()
   if h in seen:continue
   seen.add(h);obj=json.loads(b)
   text='SOURCE: '+origin(a)+'\n'+json.dumps(obj,indent=2,default=str)
   render_block(text)
   (OUT/'original_assets'/('receipt_'+str(len(seen))+'.json')).write_bytes(b)
  except Exception as e:render_block('Receipt read issue: '+origin(a)+' | '+str(e))

