def make_package():
 excludes={'FINAL_RESULTS_VISIBLE_PACKAGE.zip','FINAL_RESULTS_VISIBLE_PACKAGE.zip.tmp','PACKAGE.sha256','manifest.json'}
 members=[]
 for p in sorted(OUT.rglob('*')):
  if p.is_file() and p.name not in excludes:members.append({'file':p.relative_to(OUT).as_posix(),'bytes':p.stat().st_size,'sha256':sha_file(p)})
 js(OUT/'manifest.json',{'files':members,'new_model_fits':0,'new_PCAP_replays':0,'new_experiments':0})
 tmp=OUT/'FINAL_RESULTS_VISIBLE_PACKAGE.zip.tmp'
 with zipfile.ZipFile(tmp,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=3) as z:
  for x in members:z.write(OUT/x['file'],arcname=x['file'])
  z.write(OUT/'manifest.json',arcname='manifest.json')
 with zipfile.ZipFile(tmp) as z:
  bad=z.testzip()
  if bad:raise RuntimeError('Final ZIP corruption: '+bad)
 os.replace(tmp,OUT/'FINAL_RESULTS_VISIBLE_PACKAGE.zip')
 digest=sha_file(OUT/'FINAL_RESULTS_VISIBLE_PACKAGE.zip');(OUT/'PACKAGE.sha256').write_text(digest+'\n')
 print('\nFINAL PACKAGE:',OUT/'FINAL_RESULTS_VISIBLE_PACKAGE.zip','\nSHA256:',digest,flush=True)
 try:
  from IPython.display import display,FileLink
  display(FileLink(str(OUT/'FINAL_RESULTS_VISIBLE_PACKAGE.zip')))
  display(FileLink(str(OUT/'ALL_RESULTS_OUTPUT_CELLS.ipynb')))
 except Exception:pass

class Tee:
 def __init__(self,terminal,log):self.terminal=terminal;self.log=log
 def write(self,text):self.terminal.write(text);self.log.write(text);return len(text)
 def flush(self):self.terminal.flush();self.log.flush()
 def isatty(self):return False

